import{z as d,x as A,o as t,c as E,q as s,j as o,D as r,d as i,s as n,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"堆与优先队列","description":"","frontmatter":{"title":"堆与优先队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heap-priority.md","filePath":"cs/heap-priority.md","lastUpdated":1791063341000}'),m={name:"cs/heap-priority.md"};function B(h,a,f,T,c,u){const l=A("Mermaid");return t(),E("div",null,[a[2]||(a[2]=s('<h1 id="堆与优先队列" tabindex="-1">堆与优先队列 <a class="header-anchor" href="#堆与优先队列" aria-label="Permalink to &quot;堆与优先队列&quot;">​</a></h1><div class="epigraph"><p>只要反复取出当前最小，不必维持全部键的中序；完全二叉树里父小于子女，数组下标就能当指针。</p><footer>—— 据 Williams, Algorithm 232: Heapsort, CACM 1964；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/bplus-as-ds">上一课</a>和<a href="/cs/rbtree-intuition">红黑树直觉</a>把有序字典做到对数。优先队列的合同更窄：insert 与 extract-min（或 max），不要 successor、不要中序遍历。<a href="/cs/array-random-access">数组与随机访问</a>已经给出下标算术。<a href="/cs/amortized-analysis">摊还分析</a>不是本课必需——二叉堆单次最坏已是 \\(\\Theta(\\log n)\\)。本课不重讲 B 树分裂。缺口是堆：完全树 + 堆序，用数组表示。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用 BST 当优先队列可以，但维护全序浪费。无序数组 extract-min 要扫 \\(\\Theta(n)\\)。缺口是部分序：<strong>父键 \\(\\le\\) 子女键</strong>（最小堆），根即当前最小；形状是完全二叉树，从而高度 \\(\\lfloor\\log_2 n\\rfloor\\)，且能塞进数组：\\(i\\) 的子女 \\(2i,2i+1\\)。</p><p>insert：放末尾上滤。extract-min：用末尾填根再下滤。均为 \\(\\Theta(\\log n)\\)。建堆可以自底向上 \\(\\Theta(n)\\)，后课堆排序会用。</p><p><span class="marginnote">直觉类比：堆像公司值班表——只要求「领导永远排在下属前面」（父\\(\\le\\)子），同级同事之间不比次序，也不能按名次点名。想知道「当前最闲的人」直接看顶上那位；想找「第 7 闲的人」只能整棵翻。</span></p><p><span class="marginnote">Williams 1964 的堆排序把这套结构送进排序课。本课只交 ADT。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>抽象：优先队列。表示：数组 \\(A[1..n]\\)（或从 0 偏置）。堆不变式加形状不变式。上滤/下滤交换父与子，直到序恢复。</p>',10)),(t(),o(p,null,{default:r(()=>[n(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E6%95%B0%E7%BB%84%E5%AE%8C%E5%85%A8%E6%A0%91%22%5D%20--%3E%20ROOT%5B%22A%5B1%5D%20%E6%9C%80%E5%B0%8F%22%5D%0A%20%20ROOT%20--%3E%20L%5B%22A%5B2%5D%22%5D%0A%20%20ROOT%20--%3E%20R%5B%22A%5B3%5D%22%5D%0A%20%20L%20--%3E%20L2%5B%22A%5B4%5D%20A%5B5%5D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"decrease-key 在 Dijkstra 里需要：沿父走 \\(\\Theta(\\log n)\\)。若没有到数组下标的句柄，找元素会退回 \\(\\Theta(n)\\)。合同要声明是否提供句柄。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：从 1 起编号时，下标 5 的元素父是 \\(\\lfloor 5/2\\rfloor=2\\)，子女是 10 与 11；从 0 起编号则父是 \\(\\lfloor(i-1)/2\\rfloor\\)、子女是 \\(2i+1,2i+2\\)。一套下标算术替代全部指针，这就是「数组当树」。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"堆不支持高效查找任意键，不是字典。与 BST 分工：要序遍历用树；只要最小用堆。二项堆、斐波那契堆把 decrease-key 摊还做得更低，算法课需要时再请；主干先二叉堆。",-1)),a[7]||(a[7]=e("p",null,"一次 insert 之后，堆序怎么自己恢复：",-1)),(t(),o(p,null,{default:r(()=>[n(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22insert%3A%20%E6%96%B0%E5%85%83%E7%B4%A0%E6%94%BE%E6%9C%AB%E5%B0%BE%22%5D%20--%3E%20CMP%7B%22%E6%AF%94%E7%88%B6%E5%B0%8F%3F%22%7D%0A%20%20CMP%20--%20%22%E6%98%AF%22%20--%3E%20SWAP%5B%22%E4%B8%8E%E7%88%B6%E4%BA%A4%E6%8D%A2%2C%20%E4%B8%8A%E6%BB%A4%E4%B8%80%E5%B1%82%22%5D%0A%20%20SWAP%20--%3E%20CMP%0A%20%20CMP%20--%20%22%E5%90%A6%22%20--%3E%20DONE%5B%22%E5%A0%86%E5%BA%8F%E6%81%A2%E5%A4%8D%2C%20%E5%81%9C%E6%AD%A2%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">常见误区：初学者容易以为堆「差不多排好序」，应该能快速找第 \\(k\\) 小。实际上除了根，上层对下层只有「不大于」这一句话，找任意键就是 \\(\\Theta(n)\\) 扫描。既要按键查又要取最小，得配散列表存句柄，是后课的分工。</span></p><p>数组表示吃空间局部性：下滤走的地址仍有一定跳跃（\\(2i\\)），比链表好，比顺序扫差。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把堆排序证完，不引入 \\(d\\) 叉堆的调参。也不把操作系统的进程就绪队列写成必须用堆——那是调度课的选择。</p><p>后课默认：优先队列 = 堆合同，\\(\\Theta(\\log n)\\) 插入与取端。按任意键 \\(O(1)\\) 期望查找是散列的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>优先队列不需要全序；堆序 + 完全形状足够。</li><li>数组下标当父子，insert/extract-min 为 \\(\\Theta(\\log n)\\)。</li><li>无序键的期望 \\(O(1)\\) 查找靠下一课散列函数。</li><li>出处：Williams, <em>CACM</em>, 1964；Cormen et al. 第 6 章。</li></ul>',7))])}const _=d(m,[["render",B]]);export{C as __pageData,_ as default};
